function EulerCharacteristic(space):
  total <- 0
  for each (d, b_d) in space:
    if d is even: sign <- +1 else sign <- -1
    total <- total + sign * b_d
  return total

function Stabilize(space, n):
  shifted <- empty map
  for each (d, b_d) in space with b_d != 0:
    shifted[d + n] <- shifted[d + n] + b_d
  return shifted

